Consider the sequences \(\{w_{t}\}_{t\ge 1}\), \(\{v_{t}\}_{t\ge 1}\), and \(\{u_{t}\}_{t\ge 1}\) generated by Algorithm Adam and Eq. 4}. Under Assumptions 2.1--2.3, the following sufficient decrease inequality holds:
\begin{align}
\Pi_{\Delta,t}\hat{f}(u_{t+1})-\Pi_{\Delta,t-1}\hat{f}(u_{t})&\le-\frac{1}{2}\Pi_{\Delta,t}\sum_{i=1}^{d}\zeta_{i}(t)+C_{2}\|{\eta_{v_{t-1}}}\circ m_{t-1}\|^{2}+\sum_{i=1}^{d}\Delta_{t,i}|\nabla_{i} f(u_{t})m_{t-1,i}|\\&+(L_{f}+1)\sum_{i=1}^{d}\eta_{v_{t},i}^{2}g_{t,i}^{2}+\Pi_{\Delta,t}M_{t}.
\end{align}
Here,
\begin{align}
&\hat{f}(u_{t}):=f(u_{t})-f^*+C\sum_{i=1}^{d}\eta_{v_{t-1},i},\ \ \zeta_{i}(t):=\eta_{v_{t},i}(\nabla_{i}f(w_{t}))^{2},\\
&\Pi_{\Delta,t}:=\prod_{k=1}^{t}\left(1+\left(\frac{D_1}{1-\sqrt{\beta_{1}}}+1\right)\overline{\Delta}_{\sqrt{\beta_{1}},k}\right)^{-1}\ (t\ge 1),\ \Pi_{\Delta,0}:=1,\ \   \\&\overline{\Delta}_{\sqrt{\beta_{1}},k} := \sum_{i=1}^{d}\mathbb{E}\left[\sum_{t=k}^{+\infty} (\sqrt{\beta_{1}})^{t-k} \Delta_{t,i}\bigg|\mathscr{F}_{k-1}\right],\\
&M_{t}:=M_{t,1}+M_{t,2}+M_{t,3}.
\end{align}
Constants \( D_{1} \) is defined in Lemma D.2; \( M_{t,1} \) is defined in Eq. 19; \( M_{t,2} \) and \( M_{t,3} \) are defined in Eq. 20.

Consider the Adam algorithm defined in Algorithm Adam and suppose that Assumption 2.1$ - $2.3 hold. Then for any initial point and $\forall\ \phi>0$, we have for any $T \geq 1,$ the following inequality holds
\begin{align}
\frac{\Pi_{\Delta,T}\sqrt{S_{T}}}{(T+1)^{\phi}}\le  {\sqrt{dv}}+\sum_{t=1}^{T}\Pi_{\Delta,t}\Lambda_{\phi,t},
\end{align}
where 
\[\Lambda_{\phi,t}:=\frac{\|g_{t}\|^{2}}{(t+1)^{\phi}\sqrt{S_{t-1}}},\] and $S_{T}$ is defined in Remark 4.1.

Consider the Adam algorithm defined in Algorithm Adam and suppose that Assumptions 2.1 - 2.3 hold. Then for any initial point and for all $T \geq 1$, there exists a random variable $\zeta$ such that the following results hold
\begin{itemize}
\item[(a)] $0 \leq \zeta < +\infty$ almost surely, and $\mathbb{E}(\zeta)$ is uniformly bounded above by a constant $C_{\zeta}$, which depends on the initial point and the constants in the required assumptions (excluding $1/\mu$). The explicit form of this upper bound is provided in Equation (28).
\item[(b)] $\sqrt{S_{T}} \leq (T+1)^{4} \Pi^{-1}_{\Delta,\infty}\zeta,$ and $\ln\left(\frac{S_{T}}{v}\right)\le \ln(T+1)\zeta',$ where $\zeta'\le 4\left(1+\frac{1}{2}{\ln\left(\max\left\{e,\Pi_{\Delta,\infty}^{-1}\zeta\right\}\right)}\right).$
\end{itemize}

Consider the Adam algorithm defined in Algorithm Adam and suppose that Assumption 2.1 - 2.3 hold. Then for any initial point and $T \geq 1$, the following results hold
\begin{align*}
    \sum_{t=1}^{T}\mathbb{E}\bigg[\Pi_{\Delta,t}\sum_{i=1}^{d}\zeta_{i}(t)\bigg]\le\begin{cases} 
C_{4,\delta}, & \text{if } \delta \in (0,1], \\
C_{5}+C_{6}\mathbb{E}\left[\ln(S_{T})\right], & \text{if } \delta = 0,\end{cases}
\end{align*}
where $C_{5}$ and $C_{6}$ are constants that depend on the initial point and the constants in our required assumptions (excluding $1/\mu$), and $C_{4,\delta}$ is a constant that depends on the initial point, $\delta$, and the constants in our required assumptions (excluding $1/\mu$).

Consider the Adam algorithm defined in Algorithm Adam and assume that Assumptions 2.1 - 2.3 hold. Then, for any initial point and for all $T \geq 1$, the following results hold

- When $\delta = 0$, we have
\begin{align*}
   \sup_{t \geq 1} \frac{\Pi_{\Delta, t} (f(w_{t})-f^*)}{\ln^{2}(t+1)} < +\infty \ \ \text{a.s.,} \ \ \sup_{T \geq 1} \mathbb{E}\left[ \frac{\Pi_{\Delta, t} (f(w_{t})-f^*)}{\ln^{2}(t+1)} \right] < M_{0} < +\infty.
\end{align*}

- When $\delta > 0$, we have
\begin{align*}
   \sup_{t \geq 1} \Pi_{\Delta, t} (f(w_{t})-f^*) < +\infty \ \ \text{a.s.,} \ \ \sup_{T \geq 1} \mathbb{E}\left[ \Pi_{\Delta, t} (f(w_{t})-f^*) \right] < M_{\delta} < +\infty.
\end{align*}




In the above equations, $M_{0}$ and $M_{\delta}$ are two constants that depend on the initial point and the constants in our assumptions (excluding $1/\mu$).

Under Assumption 2.1 - 2.3, consider the Adam algorithm (Algorithm Adam) with hyperparameters in Subsection 2.4 with $\gamma>1,\  \delta>0.$ Then for any initial point, the following results hold
\begin{align*}
    \sum_{t=1}^{+\infty}\eta_{t}\|\nabla f(w_{t})\|^{2}<+\infty\ \ \text{a.s.,}\ \ \sum_{t=1}^{+\infty}\eta_{t}\|\nabla f(u_{t})\|^{2}<+\infty\ \ \text{a.s.},\ \ \text{and}\ \ 
\sum_{t=1}^{+\infty}\|\eta_{v_{t}}\circ m_{t}\|^{2} <+\infty\ \ \text{a.s.} 
\end{align*}

Let \(\{(X_n, \mathscr{F}_n)\}_{n \geq 1}\) be a non-negative adapted process such that \(\sum_{n=1}^{+\infty} X_n = M < +\infty\) almost surely, where \(M\) is a finite constant. Define the partial sum of conditional expectations as \(\Lambda_T := \sum_{n=1}^{T} \mathbb{E}[X_n \mid \mathscr{F}_{n-1}]\). Then the following properties hold.
\begin{itemize}
    \item[(i)] The sequence \(\{\Lambda_T\}_{T \geq 1}\) converges almost surely, i.e., \(\Lambda_T \xrightarrow{a.s.} \Lambda\), where \(\Lambda := \sum_{n=1}^{+\infty} \mathbb{E}[X_n \mid \mathscr{F}_{n-1}]\).

    \item[(ii)] For any \(p \geq 1\), the sequence \(\{\Lambda_T\}_{T \geq 1}\) converges in \(L_p\), i.e., \(\lim_{T \to \infty} \mathbb{E}\left[|\Lambda_T - \Lambda|^p\right] = 0\). Meanwhile, the \(p\)-th moment of the limit \(\Lambda\) is bounded by a constant \(C_{\Lambda}(p) > 0,\) where \(C_{\Lambda}(p) = o(p^{\sqrt{p}}).\)




\end{itemize}

Consider the Adam algorithm as specified in Algorithm~Adam, and assume that Assumptions~2.1--2.3 are satisfied. Then, for any initial point, any \( T \geq 1 \), and any \( s \in (0,1) \), the following bound holds with probability at least \( 1 - s \):
\begin{align*}
 \frac{1}{T}\sum_{t=1}^{T}\|\nabla f(w_{t})\|^{2}\le  \begin{cases} 
\mathcal{O}\Big(\frac{1}{s^2}\frac{1}{T^{\frac{1}{2}-\delta}}\Big), & \text{if }\delta\in(0,1/2)  \\
\mathcal{O}\Big(\frac{1}{s^2}\frac{\ln T}{\sqrt{T}}\Big), & \text{if } \gamma>1,\ \ \delta = 0\\
\mathcal{O}\Big(\frac{1}{s^2}\frac{\ln^{2} T}{\sqrt{T}}\Big), & \text{if } \gamma=1,\ \ \delta = 0.\end{cases} \tag*{}
\end{align*}
The constant implied by the \( \mathcal{O} \) notation depends on the initial point, the constants in Assumptions~2.1--2.3 (excluding \( 1/\mu \)), and the parameters \( \delta \) and \( \alpha_0 \).
